import React from 'react';
import classNames from 'classnames';
import * as styles from './SectionTitle.module.scss';

interface Props {
  theme?: {
    fontSize: {
      big: number;
    };
    fontFamily: {
      heading: string;
    };
    colors: {
      white: string;
    };
  };
  uppercase?: boolean;
  children?: React.ReactNode;
}

const SectionTitle: React.FC<Props> = ({ theme, uppercase, children }) => {
  const styleVars: React.CSSProperties = {
    ['--section-title-font-size' as any]: theme?.fontSize.big,
    ['--section-title-font-family' as any]: theme?.fontFamily.heading,
    ['--section-title-after-bg' as any]: theme?.colors.white,
  };

  return (
    <div
      className={classNames(
        styles.sectionTitle,
        { [styles.uppercase]: uppercase }
      )}
      style={styleVars}
    >
      {children}
    </div>
  );
};

export default SectionTitle;
